head.script:
(function () {
  try {
    var u = new URL(location.href);
    if (u.searchParams.has('m')) {
      u.searchParams.delete('m');
      var q = u.searchParams.toString();
      history.replaceState({}, document.title, u.pathname + (q ? '?' + q : '') + u.hash);
    }
  } catch (e) {}
  if (navigator.serviceWorker) {
    navigator.serviceWorker.getRegistrations().then(function (list) {
      for (var i = 0; i < list.length; i++) list[i].unregister();
    });
  }
})();

head.b:skin:
html,body{margin:0;background:#f4efe6;color:#17141c;font-family:system-ui,"Segoe UI",sans-serif;overflow-x:clip;-webkit-text-size-adjust:100%}
#header,#search_top,#page_list_top,#ads,#footer,#sidebar_top,#sidebar_bottom,
.hamburger-menu,.search,.blog-name,.widget.Attribution,.widget.AdSense,.widget.Profile,
#Attribution1,#Profile1,.copyright,.blog-feeds,
.widget.BlogSearch,.widget.Header,.widget.PageList,.widget.ReportAbuse,.widget.FeaturedPost,.widget.PopularPosts,.no-posts-message,
.blog-pager,.comments,.comment-form,.post-footer,.feed-links,.skip-navigation,.return_link,
a[href*="blogger.com/profile"],a[href="https://www.blogger.com"],a[href="https://www.blogger.com/"],
#cookieChoiceInfo,#cookieChoiceDismiss,.cookie-choices-info,#cookieBar,.cookieBar,
div[id*="cookieChoice"],iframe[src*="cookiechoices"]{display:none!important;height:0!important;overflow:hidden!important;visibility:hidden!important}
.page,.page_body,.widget.Blog,.blog-posts,.post-outer,.post,.widget,.widget-content{
margin:0;padding:0;border:0;background:transparent;box-shadow:none;max-width:none;width:100%
}
#yte-root{display:block;min-height:100svh;min-height:100vh;contain:layout}
@media (max-width:700px){
.yte-seo h1{font-size:1.35rem}
.yte-seo,.yte-seo-nav,.yte-seo-foot,.yte-static{width:calc(100% - 24px)}
}
#yte-root[data-yte-posts="1"]{min-height:0}
body[data-yte-posts="1"] .yte-seo,
body[data-yte-posts="1"] .yte-seo-nav,
body[data-yte-posts="1"] .yte-seo-foot{display:none!important}
.yte-seo,.yte-seo-nav,.yte-seo-foot,.yte-static{width:min(920px,calc(100% - 24px));margin:0 auto;content-visibility:auto;contain-intrinsic-size:auto 800px}
.yte-crumbs{padding:16px 0 0;font-size:13px;color:#5c5666}
.yte-crumbs a{color:#c2410c}
.yte-byline,.yte-updated{font-size:14px;color:#5c5666;margin:0 0 8px}
.yte-seo h1{font-size:1.7rem;line-height:1.2;margin:24px 0 12px}
.yte-preview{display:block;width:min(100%,640px);height:auto;margin:8px 0 20px;border-radius:14px}
.yte-seo h2{font-size:1.35rem;margin:28px 0 10px}
.yte-seo h3{font-size:1.05rem;margin:18px 0 8px}
.yte-seo p,.yte-seo li{color:#5c5666;max-width:66ch;line-height:1.65}
.yte-seo a,.yte-seo-nav a,.yte-static a{color:#c2410c}
.yte-seo-nav{display:flex;flex-wrap:wrap;gap:10px 16px;padding:20px 0 8px;font-size:14px}
.yte-seo-foot{padding:24px 0 56px;font-size:14px;color:#5c5666}
.yte-static img{display:block;max-width:min(100%,1200px);height:auto;margin:12px 0;border-radius:12px}
.yte-404{min-height:72vh;display:flex;align-items:center;justify-content:center;padding:48px 20px 80px}
.yte-404-card{width:min(520px,100%);text-align:center;background:#fff;border-radius:20px;padding:40px 28px 36px;box-shadow:0 16px 48px rgba(23,20,28,.08)}
.yte-404-code{margin:0;font-size:4rem;line-height:1;font-weight:700;letter-spacing:-.04em;color:#c2410c}
.yte-404 h1{font-size:1.45rem;margin:12px 0 8px}
.yte-404 p{margin:0 auto;max-width:40ch;color:#5c5666;line-height:1.6}
.yte-404-btn{display:inline-block;margin-top:22px;background:#c2410c;color:#fff!important;text-decoration:none;padding:12px 22px;border-radius:999px;font-weight:600}
.yte-404-btn:hover{background:#9a3412}
.yte-404-bar{height:4px;margin:28px 0 10px;background:#ece7e0;border-radius:999px;overflow:hidden}
.yte-404-bar span{display:block;height:100%;width:0;background:#c2410c;animation:yte404fill 5s linear forwards}
@keyframes yte404fill{to{width:100%}}
@media (prefers-reduced-motion:reduce){.yte-404-bar span{animation:none;width:100%}}

