body.script:
(function () {
  function muteNotice() {
    window.cookieOptions = {};
    window.cookieChoices = {
      showCookieConsentBar: function () {},
      showCookieConsentDialog: function () {}
    };
  }
  function killCookies() {
    muteNotice();
    var nodes = document.querySelectorAll('#cookieChoiceInfo,#cookieChoiceDismiss,.cookie-choices-info,#cookieBar,.cookieBar,div[id*="cookieChoice"]');
    for (var i = 0; i < nodes.length; i++) {
      var el = nodes[i];
      if (el.parentNode) el.parentNode.removeChild(el);
    }
    try { document.cookie = 'displayCookieNotice=y; path=/; max-age=31536000; SameSite=Lax'; } catch (e) {}
  }
  function strip() {
    var nodes = document.querySelectorAll('link[rel="me"], a[href*="blogger.com/profile"]');
    for (var i = 0; i < nodes.length; i++) {
      var el = nodes[i];
      if (el.parentNode) el.parentNode.removeChild(el);
    }
    killCookies();
  }
  muteNotice();
  strip();
  document.addEventListener('DOMContentLoaded', function () {
    muteNotice();
    killCookies();
  });
  if (window.MutationObserver) {
    new MutationObserver(killCookies).observe(document.documentElement, {childList: true, subtree: true});
  }
  setTimeout(killCookies, 0);
  setTimeout(killCookies, 400);
  setTimeout(killCookies, 1500);
})();

b:if.script:
(function () {
  function wire() {
    var host = document.getElementById('yte-root');
    if (!host || !host.shadowRoot) return false;
    var brand = host.shadowRoot.querySelector('.yte-brand');
    if (!brand) return false;
    if (brand.tagName !== 'A') {
      var a = document.createElement('a');
      a.className = brand.className;
      a.setAttribute('href', 'https://www.11tik.com/');
      while (brand.firstChild) a.appendChild(brand.firstChild);
      if (brand.parentNode) brand.parentNode.replaceChild(a, brand);
    } else {
      brand.setAttribute('href', 'https://www.11tik.com/');
    }
    return true;
  }
  if (wire()) return;
  var host = document.getElementById('yte-root');
  if (!host || !window.MutationObserver) {
    setTimeout(wire, 400);
    return;
  }
  var obs = new MutationObserver(function () { if (wire()) obs.disconnect(); });
  obs.observe(host, {childList: true, subtree: true});
  setTimeout(function () { obs.disconnect(); }, 4000);
})();

body.script:
(function stampImages() {
  function visit(root) {
    if (!root || !root.querySelectorAll) return;
    var imgs = root.querySelectorAll("img");
    for (var i = 0; i < imgs.length; i++) {
      var img = imgs[i];
      var alt = (img.getAttribute("alt") || "").trim() || document.title || "11tik YouTube thumbnail";
      img.setAttribute("alt", alt);
      if (!(img.getAttribute("title") || "").trim()) img.setAttribute("title", alt);
    }
    var all = root.querySelectorAll("*");
    for (var j = 0; j < all.length; j++) if (all[j].shadowRoot) visit(all[j].shadowRoot);
  }
  function run() { visit(document); }
  run();
  if (window.MutationObserver) new MutationObserver(run).observe(document.documentElement, { childList: true, subtree: true });
})();

b:if.script:
(function () {
  function clip(value) {
    return String(value || "").replace(/\s+/g, " ").trim().slice(0, 150);
  }
  function isJunk(value) {
    return /Last updated:|By 11tik|Download YouTube thumbnails instantly|Paste a video or Shorts URL/i.test(value || "");
  }
  function fromPage() {
    var p = document.querySelector("[itemprop='description']");
    if (p) {
      var d = clip(p.textContent);
      if (d.length > 40 && !isJunk(d)) return d;
    }
    return "";
  }
  function apply() {
    var head = document.querySelector("meta[name='description']");
    var curHead = head && head.getAttribute("content") || "";
    if (curHead && !isJunk(curHead) && curHead.length > 40) return;
    var next = fromPage();
    if (!next) return;
    var sels = ["meta[name='description']", "meta[property='og:description']", "meta[name='twitter:description']"];
    for (var i = 0; i < sels.length; i++) {
      var el = document.querySelector(sels[i]);
      if (!el) {
        el = document.createElement("meta");
        if (sels[i].indexOf("og:") >= 0) el.setAttribute("property", "og:description");
        else el.setAttribute("name", sels[i].indexOf("twitter") >= 0 ? "twitter:description" : "description");
        document.head.appendChild(el);
      }
      var cur = el.getAttribute("content") || "";
      if (!cur || isJunk(cur)) el.setAttribute("content", next);
    }
  }
  apply();
  document.addEventListener("DOMContentLoaded", apply);
})();
